import{_ as a,o as e,c as l,a4 as s}from"./chunks/framework.BUqnS5H7.js";const m=JSON.parse('{"title":"消息队列选型","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/01-intro/chapter-03-mq-comparison.md","filePath":"kafka/01-intro/chapter-03-mq-comparison.md"}'),n={name:"kafka/01-intro/chapter-03-mq-comparison.md"};function i(d,t,r,c,o,f){return e(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="消息队列选型" tabindex="-1" data-src-line="1" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">消息队列选型 <a class="header-anchor" href="#消息队列选型" aria-label="Permalink to &quot;消息队列选型&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><p data-src-line="3" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">选消息队列不是选「最好的」，而是选「最适合的」。本章从技术维度和业务维度对比主流消息队列，给出选型决策树。</p></blockquote><h2 id="_1-主流消息队列" tabindex="-1" data-src-line="5" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">1. 主流消息队列 <a class="header-anchor" href="#_1-主流消息队列" aria-label="Permalink to &quot;1. 主流消息队列&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="7" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">特性</th><th style="text-align:left;">Kafka</th><th style="text-align:left;">RabbitMQ</th><th style="text-align:left;">RocketMQ</th><th style="text-align:left;">Pulsar</th></tr></thead><tbody data-src-line="9" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="9" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">开发语言</td><td style="text-align:left;">Java/Scala</td><td style="text-align:left;">Erlang</td><td style="text-align:left;">Java</td><td style="text-align:left;">Java</td></tr><tr data-src-line="10" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">吞吐量</td><td style="text-align:left;">百万级</td><td style="text-align:left;">万级</td><td style="text-align:left;">十万级</td><td style="text-align:left;">百万级</td></tr><tr data-src-line="11" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">延迟</td><td style="text-align:left;">毫秒</td><td style="text-align:left;">微秒</td><td style="text-align:left;">毫秒</td><td style="text-align:left;">毫秒</td></tr><tr data-src-line="12" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息模型</td><td style="text-align:left;">发布订阅</td><td style="text-align:left;">队列/发布订阅</td><td style="text-align:left;">队列/发布订阅</td><td style="text-align:left;">发布订阅</td></tr><tr data-src-line="13" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息回溯</td><td style="text-align:left;">✅</td><td style="text-align:left;">❌</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td></tr><tr data-src-line="14" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">事务消息</td><td style="text-align:left;">✅</td><td style="text-align:left;">❌</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td></tr><tr data-src-line="15" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">流处理</td><td style="text-align:left;">✅ Streams</td><td style="text-align:left;">❌</td><td style="text-align:left;">❌</td><td style="text-align:left;">✅</td></tr><tr data-src-line="16" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">社区活跃</td><td style="text-align:left;">极高</td><td style="text-align:left;">高</td><td style="text-align:left;">高</td><td style="text-align:left;">高</td></tr></tbody></table><h2 id="_2-核心差异分析" tabindex="-1" data-src-line="18" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2. 核心差异分析 <a class="header-anchor" href="#_2-核心差异分析" aria-label="Permalink to &quot;2. 核心差异分析&quot;">​</a></h2><h3 id="_2-1-吞吐量差异的根因" tabindex="-1" data-src-line="20" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2.1 吞吐量差异的根因 <a class="header-anchor" href="#_2-1-吞吐量差异的根因" aria-label="Permalink to &quot;2.1 吞吐量差异的根因&quot;">​</a></h3><table tabindex="0"><thead data-src-line="22" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="22" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">因素</th><th style="text-align:left;">Kafka</th><th style="text-align:left;">RabbitMQ</th></tr></thead><tbody data-src-line="24" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="24" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">存储方式</td><td style="text-align:left;">追加日志，顺序写入 O(1)</td><td style="text-align:left;">B+ 树 / 链表，随机写入</td></tr><tr data-src-line="25" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">零拷贝</td><td style="text-align:left;">sendfile() 跳过用户态</td><td style="text-align:left;">需要拷贝到用户态</td></tr><tr data-src-line="26" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">批量发送</td><td style="text-align:left;">原生支持 batch</td><td style="text-align:left;">逐条推送</td></tr><tr data-src-line="27" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息堆积</td><td style="text-align:left;">磁盘顺序读，不影响性能</td><td style="text-align:left;">堆积后性能下降</td></tr></tbody></table><h3 id="_2-2-消费模型差异" tabindex="-1" data-src-line="29" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2.2 消费模型差异 <a class="header-anchor" href="#_2-2-消费模型差异" aria-label="Permalink to &quot;2.2 消费模型差异&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kafka（Pull）：</span></span>
<span class="line"><span>  Consumer → Broker：给我 Partition 0 从 offset 100 开始的消息</span></span>
<span class="line"><span>  消费者控制速率，不会因推送风暴而不可用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RabbitMQ（Push）：</span></span>
<span class="line"><span>  Broker → Consumer：这是新消息，你处理吧</span></span>
<span class="line"><span>  Broker 推送速率可能超过消费者处理能力</span></span></code></pre></div><p data-src-line="41" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">Pull 模型的优势：消费者控制消费速率、支持批量拉取、消费者宕机不影响 Broker。</p><p data-src-line="43" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">Push 模型的优势：实时性更好（消息到达即推送）、消费者实现更简单。</p><h3 id="_2-3-消息可靠性" tabindex="-1" data-src-line="45" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2.3 消息可靠性 <a class="header-anchor" href="#_2-3-消息可靠性" aria-label="Permalink to &quot;2.3 消息可靠性&quot;">​</a></h3><table tabindex="0"><thead data-src-line="47" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="47" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Kafka</th><th style="text-align:left;">RabbitMQ</th><th style="text-align:left;">RocketMQ</th></tr></thead><tbody data-src-line="49" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="49" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息持久化</td><td style="text-align:left;">磁盘（可配置保留时间）</td><td style="text-align:left;">磁盘（确认后持久化）</td><td style="text-align:left;">磁盘</td></tr><tr data-src-line="50" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">副本机制</td><td style="text-align:left;">ISR，可配置副本因子</td><td style="text-align:left;">镜像队列</td><td style="text-align:left;">同步双写</td></tr><tr data-src-line="51" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">事务</td><td style="text-align:left;">0.11+ 支持</td><td style="text-align:left;">不支持</td><td style="text-align:left;">支持（半消息）</td></tr><tr data-src-line="52" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息丢失窗口</td><td style="text-align:left;">acks=all 时几乎无</td><td style="text-align:left;">消费者确认前可能丢</td><td style="text-align:left;">同步模式几乎无</td></tr></tbody></table><h2 id="_3-选型决策树" tabindex="-1" data-src-line="54" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">3. 选型决策树 <a class="header-anchor" href="#_3-选型决策树" aria-label="Permalink to &quot;3. 选型决策树&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需要消息队列</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 高吞吐（&gt;10万/s）+ 大数据生态 → Kafka</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 业务消息 + 复杂路由 + 低延迟 → RabbitMQ</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 金融级事务 + 延迟消息 → RocketMQ</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ 多租户 + 存储分离 → Pulsar</span></span></code></pre></div><h2 id="_4-场景选型" tabindex="-1" data-src-line="68" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">4. 场景选型 <a class="header-anchor" href="#_4-场景选型" aria-label="Permalink to &quot;4. 场景选型&quot;">​</a></h2><table tabindex="0"><thead data-src-line="70" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="70" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">场景</th><th style="text-align:left;">推荐</th><th style="text-align:left;">理由</th></tr></thead><tbody data-src-line="72" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="72" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">日志收集</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">高吞吐、消息回溯、ELK 生态</td></tr><tr data-src-line="73" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">事件驱动</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">高吞吐、持久化、消费者组</td></tr><tr data-src-line="74" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">数据管道（CDC）</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">Kafka Connect、Debezium 生态</td></tr><tr data-src-line="75" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">流式处理</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">Kafka Streams / Flink 集成</td></tr><tr data-src-line="76" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">业务消息（订单/支付）</td><td style="text-align:left;">RabbitMQ 或 RocketMQ</td><td style="text-align:left;">低延迟、复杂路由、事务支持</td></tr><tr data-src-line="77" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">即时通讯</td><td style="text-align:left;">RabbitMQ</td><td style="text-align:left;">微秒级延迟、灵活路由</td></tr><tr data-src-line="78" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">金融交易</td><td style="text-align:left;">RocketMQ</td><td style="text-align:left;">事务消息、定时消息、高可靠</td></tr></tbody></table><h2 id="_5-何时不选-kafka" tabindex="-1" data-src-line="80" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">5. 何时不选 Kafka <a class="header-anchor" href="#_5-何时不选-kafka" aria-label="Permalink to &quot;5. 何时不选 Kafka&quot;">​</a></h2><table tabindex="0"><thead data-src-line="82" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="82" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">场景</th><th style="text-align:left;">原因</th><th style="text-align:left;">替代方案</th></tr></thead><tbody data-src-line="84" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="84" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息量 &lt; 1万/s</td><td style="text-align:left;">Kafka 运维成本高，杀鸡用牛刀</td><td style="text-align:left;">RabbitMQ</td></tr><tr data-src-line="85" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">延迟要求 &lt; 1ms</td><td style="text-align:left;">Kafka 毫秒级，RabbitMQ 微秒级</td><td style="text-align:left;">RabbitMQ</td></tr><tr data-src-line="86" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">复杂路由规则</td><td style="text-align:left;">Kafka 只支持 Topic 级路由</td><td style="text-align:left;">RabbitMQ（Exchange/Binding）</td></tr><tr data-src-line="87" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">小团队无 Java 技术栈</td><td style="text-align:left;">Kafka 运维需要 JVM 经验</td><td style="text-align:left;">RabbitMQ 或云服务</td></tr></tbody></table><h2 id="_6-混合使用" tabindex="-1" data-src-line="89" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">6. 混合使用 <a class="header-anchor" href="#_6-混合使用" aria-label="Permalink to &quot;6. 混合使用&quot;">​</a></h2><p data-src-line="91" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">大型系统中可以同时使用多种消息队列：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务消息（订单/支付）→ RabbitMQ（低延迟、复杂路由）</span></span>
<span class="line"><span>日志/事件           → Kafka（高吞吐、持久化）</span></span>
<span class="line"><span>数据管道            → Kafka Connect（CDC 生态）</span></span></code></pre></div><blockquote data-src-line="99" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><p data-src-line="99" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">不要为了「统一技术栈」而强行用一个消息队列解决所有问题。Kafka 擅长大数据量、高吞吐；RabbitMQ 擅长业务消息、灵活路由。各取所长。</p></blockquote>`,23)])])}const h=a(n,[["render",i]]);export{m as __pageData,h as default};
